class ConstraintLayoutDetector : Detector(), XmlScanner {

    override fun appliesTo(folderType: ResourceFolderType) = folderType == ResourceFolderType.LAYOUT

    override fun getApplicableElements(): Collection<String> = CONSTRAINT_LAYOUTS

    override fun visitElement(context: XmlContext, element: Element) {
        if (!CONSTRAINT_LAYOUTS.contains(element.tagName)) {
            return
        }
        var child = element.firstChild
        while (child != null) {
            if (child.nodeType == Node.ELEMENT_NODE) {
                val childElement = child as Element
                if (CONSTRAINT_LAYOUTS.contains(childElement.tagName)) {
                    // Will be analyzed separately
                } else {
                    checkElement(context, childElement)
                }
            }
            child = child.nextSibling
        }
    }

    private fun checkElement(context: XmlContext, element: Element) {
        val tag = element.tagName
        when {
            tag.endsWith("Guideline") -> return
            tag.endsWith("Barrier") || tag.endsWith("Group") || tag.endsWith("Flow") || tag.endsWith("Layer") -> {
                if (!element.hasAttributeNS(AUTO_URI, ATTR_CONSTRAINT_REFERENCED_IDS)) {
                    reportMissing(context, element)
                }
                return
            }
            tag.endsWith("ConstraintSet") -> return
            tag == "include" || tag == "merge" -> return
            else -> checkWidget(context, element)
        }
    }

    private fun checkWidget(context: XmlContext, element: Element) {
        val hasHorizontal = HORIZONTAL_CONSTRAINTS.any { element.hasAttributeNS(AUTO_URI, it) }
        val hasVertical = VERTICAL_CONSTRAINTS.any { element.hasAttributeNS(AUTO_URI, it) }
        val widthMatchParent = element.getAttributeNS(ANDROID_URI, ATTR_LAYOUT_WIDTH) == VALUE_MATCH_PARENT
        val heightMatchParent = element.getAttributeNS(ANDROID_URI, ATTR_LAYOUT_HEIGHT) == VALUE_MATCH_PARENT
        if (!hasHorizontal && !widthMatchParent) {
            reportMissing(context, element, true)
        }
        if (!hasVertical && !heightMatchParent) {
            reportMissing(context, element, false)
        }
    }

    private fun reportMissing(context: XmlContext, element: Element) {
        context.report(ISSUE, element, context.getElementLocation(element),
                "This view is not constrained. Add a constraint.")
    }

    private fun reportMissing(context: XmlContext, element: Element, horizontal: Boolean) {
        val attrName = if (horizontal) ATTR_LAYOUT_EDITOR_ABSOLUTE_X else ATTR_LAYOUT_EDITOR_ABSOLUTE_Y
        val attribute = element.getAttributeNodeNS(TOOLS_URI, attrName)
        val message: String
        val location = if (attribute != null) {
            message = "This view is not constrained ${if (horizontal) "horizontally" else "vertically"}: only ${attribute.name} was set to ${attribute.value}. Add a ${if (horizontal) "horizontal" else "vertical"} constraint."
            context.getElementLocation(element)
        } else {
            message = "This view is not constrained ${if (horizontal) "horizontally" else "vertically"}. Add a ${if (horizontal) "horizontal" else "vertical"} constraint."
            context.getElementLocation(element)
        }
        context.report(ISSUE, element, location, message)
    }

    companion object {
        ...
    }
}
